WITH store_customer AS ( SELECT ss.ss_customer_sk AS customer_id, SUM(ss.ss_ext_discount_amt) AS total_discount, SUM(ss.ss_ext_sales_price) AS total_sales, SUM(ss.ss_net_paid) AS total_net_paid, 'Store' AS channel, NULL AS warehouse_name FROM store_sales ss JOIN item i ON ss.ss_item_sk = i.i_item_sk WHERE i.i_category = 'Home' GROUP BY ss.ss_customer_sk ), web_customer AS ( SELECT ws.ws_bill_customer_sk AS customer_id, SUM(ws.ws_ext_discount_amt) AS total_discount, SUM(ws.ws_ext_sales_price) AS total_sales, SUM(ws.ws_net_paid) AS total_net_paid, 'Web' AS channel, w.w_warehouse_name AS warehouse_name FROM web_sales ws JOIN item i ON ws.ws_item_sk = i.i_item_sk JOIN warehouse w ON ws.ws_warehouse_sk = w.w_warehouse_sk WHERE i.i_category = 'Home' GROUP BY ws.ws_bill_customer_sk, w.w_warehouse_name ), all_customers AS ( SELECT * FROM store_customer UNION ALL SELECT * FROM web_customer ) SELECT ac.customer_id, ac.channel, ac.total_discount, ac.total_sales, ac.total_net_paid, CASE WHEN ac.total_sales > 0 THEN ac.total_discount / ac.total_sales ELSE 0 END AS discount_ratio, CASE WHEN (CASE WHEN ac.total_sales > 0 THEN ac.total_discount / ac.total_sales ELSE 0 END) > 0.20 THEN 'High Discount' ELSE 'Normal Discount' END AS discount_flag, ROW_NUMBER() OVER (PARTITION BY ac.channel ORDER BY ac.total_net_paid DESC) AS customer_rank, COALESCE(ac.warehouse_name, 'N/A') AS warehouse_name FROM all_customers ac WHERE ac.total_sales > 0 ORDER BY ac.channel, customer_rank LIMIT 30
